import React, { useState } from "react";
import axios from "axios";

function ApplicationsTable({ applications, onRefresh }) {
  const [selectedApp, setSelectedApp] = useState(null);
  const [rejecting, setRejecting] = useState(null);
  const [accepting, setAccepting] = useState(null); // Added for Accept button
  const [filterStatus, setFilterStatus] = useState("all");

  const handleReject = async (app) => {
    if (!window.confirm(`Are you sure you want to reject ${app.name}'s application? A rejection email will be sent to ${app.email}`)) {
      return;
    }

    setRejecting(app._id);
    try {
      await axios.post(`http://localhost:5000/api/applications/${app._id}/reject`);
      alert(`Rejection email sent successfully to ${app.email}!`);
      if (onRefresh) onRefresh(); // Refresh the applications list
    } catch (err) {
      console.error("Error rejecting application:", err);
      alert("Failed to reject application. Check console for details.");
    }
    setRejecting(null);
  };

  const handleAccept = async (app) => {
    if (!window.confirm(`Are you sure you want to accept ${app.name}'s application? An acceptance email will be sent to ${app.email}`)) {
      return;
    }

    setAccepting(app._id);
    try {
      await axios.post(`http://localhost:5000/api/applications/${app._id}/accept`);
      alert(`Application accepted successfully and email sent to ${app.email}!`);
      if (onRefresh) onRefresh(); // Refresh the applications list
    } catch (err) {
      console.error("Error accepting application:", err);
      alert("Failed to accept application. Check console for details.");
    }
    setAccepting(null);
  };

  const filteredApplications = applications.filter(app => {
    if (filterStatus === "all") return true;
    return app.status === filterStatus;
  });

  return (
    <div style={containerStyle}>
      {/* Filter Dropdown */}
      <div style={{ marginBottom: "16px" }}>
        <label style={{ marginRight: "8px", fontWeight: "500" }}>Filter by Status:</label>
        <select 
          value={filterStatus} 
          onChange={(e) => setFilterStatus(e.target.value)}
          style={{ padding: "6px 12px", borderRadius: "6px", border: "1px solid #cbd5e1" }}
        >
          <option value="all">All</option>
          <option value="pending">Pending</option>
          <option value="accepted">Accepted</option>
          <option value="rejected">Rejected</option>
        </select>
      </div>

      {filteredApplications.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No applications found.</p>
      ) : (
        <table style={tableStyle}>
          <thead style={theadStyle}>
            <tr>
              <th style={thStyle}>Name</th>
              <th style={thStyle}>E-mail Id</th>
              <th style={thStyle}>Phone Number</th>
              <th style={thStyle}>Resume</th>
              <th style={thStyle}>Skill Set</th>
              <th style={thStyle}>Status</th>
              <th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredApplications.map((app) => (
              <tr key={app._id} style={trStyle}>
                <td style={tdStyle}>{app.name || "NA"}</td>
                <td style={tdStyle}>{app.email || "NA"}</td>
                <td style={tdStyle}>{app.phone || "NA"}</td>
                <td style={tdStyle}>
                  {app.resumeUrl && app.resumeUrl !== "NA" ? (
                    <a href={app.resumeUrl} target="_blank" rel="noopener noreferrer" style={linkStyle}>
                      View Resume
                    </a>
                  ) : "NA"}
                </td>
                <td style={tdStyle}>{app.skillset || "NA"}</td>
                <td style={tdStyle}>
                  <span style={getStatusStyle(app.status)}>
                    {app.status === "rejected" ? "Rejected" : app.status === "accepted" ? "Accepted" : "Pending"}
                  </span>
                </td>
                <td style={tdStyle}>
                  <div style={{ display: "flex", gap: "8px" }}>
                    <button style={btnStyle} onClick={() => setSelectedApp(app)}>View Details</button>
                    {app.status !== "rejected" && (
                      <button 
                        style={{...btnStyle, ...rejectBtnStyle}} 
                        onClick={() => handleReject(app)}
                        disabled={rejecting === app._id}
                      >
                        {rejecting === app._id ? "Rejecting..." : "Reject"}
                      </button>
                    )}
                    {app.status !== "accepted" && (
                      <button 
                        style={{...btnStyle, background: "#16a34a"}} 
                        onClick={() => handleAccept(app)}
                        disabled={accepting === app._id}
                      >
                        {accepting === app._id ? "Accepting..." : "Accept"}
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* Modal code remains exactly the same */}
      {selectedApp && (
        <div style={modalOverlay}>
          {/* ... modal content here ... */}
        </div>
      )}
    </div>
  );
}


    <div style={containerStyle}>
      {applications.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No applications received yet.</p>
      ) : (
        <table style={tableStyle}>
          <thead style={theadStyle}>
            <tr>
              <th style={thStyle}>Name</th>
              <th style={thStyle}>E-mail Id</th>
              <th style={thStyle}>Phone Number</th>
              <th style={thStyle}>Resume</th>
              <th style={thStyle}>Skill Set</th>
              <th style={thStyle}>Status</th>
              <th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {applications.map((app) => (
              <tr key={app._id} style={trStyle}>
                <td style={tdStyle}>{app.name || "NA"}</td>
                <td style={tdStyle}>{app.email || "NA"}</td>
                <td style={tdStyle}>{app.phone || "NA"}</td>
                <td style={tdStyle}>
                  {app.resumeUrl && app.resumeUrl !== "NA" ? (
                    <a href={app.resumeUrl} target="_blank" rel="noopener noreferrer" style={linkStyle}>
                      View Resume
                    </a>
                  ) : "NA"}
                </td>
                <td style={tdStyle}>{app.skillset || "NA"}</td>
                <td style={tdStyle}>
                  <span style={getStatusStyle(app.status)}>
                    {app.status === "rejected" ? "Rejected" : app.status === "accepted" ? "Accepted" : "Pending"}
                  </span>
                </td>
                <td style={tdStyle}>
                  <div style={{ display: "flex", gap: "8px" }}>
                    <button style={btnStyle} onClick={() => setSelectedApp(app)}>
                      View Details
                    </button>
                    {app.status !== "rejected" && (
                      <button 
                        style={{...btnStyle, ...rejectBtnStyle}} 
                        onClick={() => handleReject(app)}
                        disabled={rejecting === app._id}
                      >
                        {rejecting === app._id ? "Rejecting..." : "Reject"}
                      </button>
                    )}
                    {app.status !== "accepted" && (
                      <button 
                        style={{...btnStyle, background: "#16a34a"}} 
                        onClick={() => handleAccept(app)}
                        disabled={accepting === app._id}
                      >
                        {accepting === app._id ? "Accepting..." : "Accept"}
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* Modal for full details */}
      {selectedApp && (
        <div style={modalOverlay}>
          <div style={modalContainer}>
            <div style={modalHeader}>
              <h2 style={modalTitle}>Application Details</h2>
              <button style={closeBtn} onClick={() => setSelectedApp(null)}>✕</button>
            </div>

            <div style={modalContent}>
              {/* Personal Info */}
              <div style={detailSection}>
                <h3 style={sectionTitle}>Personal Information</h3>
                <p style={detailItem}><strong>Name:</strong> {selectedApp.name || "NA"}</p>
                <p style={detailItem}><strong>Email:</strong> {selectedApp.email || "NA"}</p>
                <p style={detailItem}><strong>Phone:</strong> {selectedApp.phone || "NA"}</p>
                <p style={detailItem}><strong>Location:</strong> {selectedApp.location || "NA"}</p>
                <p style={detailItem}><strong>Pincode:</strong> {selectedApp.pincode || "NA"}</p>
                <p style={detailItem}><strong>Address:</strong> {selectedApp.address || "NA"}</p>
              </div>

              {/* Professional Info */}
              <div style={detailSection}>
                <h3 style={sectionTitle}>Professional Information</h3>
                <p style={detailItem}><strong>Skillset:</strong> {selectedApp.skillset || "NA"}</p>
                <p style={detailItem}><strong>Job Applied For:</strong> {selectedApp.jobTitle || "NA"}</p>
                <p style={detailItem}><strong>Resume:</strong>{" "}
                  {selectedApp.resumeUrl && selectedApp.resumeUrl !== "NA" ? (
                    <a href={selectedApp.resumeUrl} target="_blank" rel="noopener noreferrer" style={linkStyle}>
                      View Resume
                    </a>
                  ) : "NA"}
                </p>
                <p style={detailItem}><strong>Project Details:</strong> {selectedApp.project || "NA"}</p>
              </div>

              {/* Academic Info */}
              {selectedApp.academic && (
                <div style={detailSection}>
                  <h3 style={sectionTitle}>Academic Details</h3>
                  {selectedApp.academic.tenth && (
                    <div style={academicBlock}>
                      <strong>10th Standard:</strong>
                      <p>Score: {selectedApp.academic.tenth.score || "NA"}</p>
                      <p>School: {selectedApp.academic.tenth.school || "NA"}</p>
                    </div>
                  )}
                  {selectedApp.academic.diploma && (
                    <div style={academicBlock}>
                      <strong>12th/Diploma:</strong>
                      <p>Score: {selectedApp.academic.diploma.score || "NA"}</p>
                      <p>College: {selectedApp.academic.diploma.college || "NA"}</p>
                      <p>Stream: {selectedApp.academic.diploma.stream || "NA"}</p>
                    </div>
                  )}
                  {selectedApp.academic.graduation && (
                    <div style={academicBlock}>
                      <strong>Graduation:</strong>
                      <p>Score: {selectedApp.academic.graduation.score || "NA"}</p>
                      <p>College: {selectedApp.academic.graduation.college || "NA"}</p>
                      <p>Stream: {selectedApp.academic.graduation.stream || "NA"}</p>
                    </div>
                  )}
                  {selectedApp.academic.postGraduation && selectedApp.academic.postGraduation.score && (
                    <div style={academicBlock}>
                      <strong>Post Graduation:</strong>
                      <p>Score: {selectedApp.academic.postGraduation.score || "NA"}</p>
                      <p>College: {selectedApp.academic.postGraduation.college || "NA"}</p>
                      <p>Stream: {selectedApp.academic.postGraduation.stream || "NA"}</p>
                    </div>
                  )}
                </div>
              )}

              {/* Status */}
              <div style={detailSection}>
                <p style={detailItem}>
                  <strong>Status:</strong>{" "}
                  <span style={getStatusStyle(selectedApp.status)}>
                    {selectedApp.status === "rejected" ? "Rejected" : selectedApp.status === "accepted" ? "Accepted" : "Pending"}
                  </span>
                </p>
                <p style={detailItem}>
                  <strong>Applied At:</strong> {new Date(selectedApp.appliedAt).toLocaleString()}
                </p>
              </div>
            </div>

            <div style={modalFooter}>
              {selectedApp.status !== "rejected" && (
                <button 
                  style={{...btnStyle, ...rejectBtnStyle, marginRight: "10px"}} 
                  onClick={() => {
                    handleReject(selectedApp);
                    setSelectedApp(null);
                  }}
                  disabled={rejecting === selectedApp._id}
                >
                  {rejecting === selectedApp._id ? "Rejecting..." : "Reject Application"}
                </button>
              )}
              {selectedApp.status !== "accepted" && (
                <button 
                  style={{...btnStyle, background: "#16a34a", marginRight: "10px"}} 
                  onClick={() => {
                    handleAccept(selectedApp);
                    setSelectedApp(null);
                  }}
                  disabled={accepting === selectedApp._id}
                >
                  {accepting === selectedApp._id ? "Accepting..." : "Accept Application"}
                </button>
              )}

              <button style={btnStyle} onClick={() => setSelectedApp(null)}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>



